(()=>{const root=document.getElementById('studio-multistream');if(!root)return;const status=root.querySelector('[role=status]'),list=root.querySelector('ul'),refresh=root.querySelector('[data-refresh]'),start=root.querySelector('[data-start]'),stop=root.querySelector('[data-stop]'),consoleLink=root.querySelector('a');let busy=false;
async function run(action){if(busy)return;if(action&&!window.confirm(action==='start'?'Start the server’s configured broadcast? Review destinations, source and any public watch page in the server console first. This uses the server source, not automatically the browser cameras.':'Stop the server broadcast now?'))return;busy=true;start.disabled=stop.disabled=refresh.disabled=true;try{let r=await fetch('/api/studio/multistream',{method:action?'POST':'GET',headers:action?{'content-type':'application/json'}:{},body:action?JSON.stringify({action,confirmed:true}):undefined});let data=await r.json();if(!r.ok)throw Error(data.error||'Broadcast check failed');if(action){if(!data.accepted)throw Error(data.message||'Broadcast action unavailable');r=await fetch('/api/studio/multistream');data=await r.json();if(!r.ok)throw Error('Action accepted. Status refresh failed; check the server console before retrying.');}status.textContent=data.message||(data.connected?'Server pipeline: '+data.state+' · Checked '+new Date(data.checkedAt).toLocaleTimeString():'Broadcast server disconnected');list.replaceChildren();consoleLink.hidden=true;if(data.connected){consoleLink.href=data.console;consoleLink.hidden=false;for(const d of data.destinations){const li=document.createElement('li');li.textContent=d.name+' · '+(d.enabled?'Enabled':'Disabled');list.append(li);}start.disabled=stop.disabled=false;}}catch(e){status.textContent=e.message;}finally{busy=false;refresh.disabled=false;}}
refresh.onclick=()=>run();start.onclick=()=>run('start');stop.onclick=()=>run('stop');window.addEventListener('studio-broadcast-open',()=>run());})();
